<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyApiApprovalFixture.php';
require_once __DIR__.'/fixtures/NativeBusinessMutationFixture.php';
use DigiForge\Connector\Printify\{NativeBusinessMutationAssociation as Association,NativeHeldJournalSchema,NativeHeldJournal,NativeBridge};
use DigiForge\Database\Tables;
final class NativeBusinessAssociationFenceTest extends WP_UnitTestCase {
 use NativeBusinessMutationFixture;
 private PrintifyApiApprovalFixture $fixture;private array $snapshots=[];
 protected function setUp():void{parent::setUp();remove_filter('query',[$this,'_create_temporary_tables']);remove_filter('query',[$this,'_drop_temporary_tables']);PortalAccessFixture::reset();DigiForge\Core\Activator::activate();$this->fixture=new PrintifyApiApprovalFixture();$this->fixture->boot();global $wpdb;foreach([Tables::opportunities(),Tables::product_families(),Tables::products(),Tables::product_versions(),Tables::production_plans(),Tables::pod_mappings(),Tables::pod_business_mappings(),Tables::asset_specs(),Tables::production_plan_assets()]as $t)$this->snapshots[$t]=$wpdb->get_results('SELECT * FROM '.$t,ARRAY_A);DigiForge\Core\Settings::protectProduction();}
 protected function tearDown():void{try{global $wpdb;$wpdb->query('ROLLBACK');foreach(NativeHeldJournalSchema::tables()as $t)$wpdb->query('DROP TABLE IF EXISTS '.$t);foreach($this->snapshots as $t=>$rows){$wpdb->query('DELETE FROM '.$t);foreach($rows as $r)$wpdb->insert($t,$r,array_fill(0,count($r),'%s'));}$this->fixture->restore();}finally{parent::tearDown();}}
 public function testGenericLocalApprovalCannotForgeLockedAssociationProducerEvidence():void {
  $f=$this->businessMutationFixture($this->fixture);$scope=$f['scope'];$m=$f['mapping_id'];$s=$f['spec_id'];$plan=$f['plan_hash'];$source=PrintifyApiApprovalFixture::checked(Association::source($scope,1,$m,$s,$plan));
  $p=PrintifyApiApprovalFixture::checked(Association::propose($scope,1,$m,$s,$plan,$source['source_hash'],0,time(),time()+1200,wp_generate_uuid4()));
  $key='native-mutation-source:'.DigiForge\Connector\Printify\NativePortContract::hash([$scope->shopKey,$scope->integrationId,$scope->providerShopId,$scope->environment,$source['product_id']]);
  PortalAccessFixture::login($this->fixture->reviewer);PrintifyApiApprovalFixture::checked(DigiForge\Security\ReviewedLocalEvidence::decide('policy',$scope->shopKey,$key,1,$p['proposal_hash'],'APPROVED',wp_generate_uuid4()));$this->fixture->owner();
  self::assertWPError(Association::read($scope,1,$m,$s,$plan),'A generic policy decision must not masquerade as the locked native association producer.');
  $next=PrintifyApiApprovalFixture::checked(Association::propose($scope,1,$m,$s,$plan,$source['source_hash'],2,time(),time()+1200,wp_generate_uuid4()));PortalAccessFixture::login($this->fixture->reviewer);PrintifyApiApprovalFixture::checked(Association::decide($scope,$this->fixture->reviewer,$m,$s,$plan,3,$next['proposal_hash'],'APPROVED',wp_generate_uuid4()));$this->fixture->owner();
  $a=PrintifyApiApprovalFixture::checked(Association::read($scope,1,$m,$s,$plan));self::assertTrue($a['business_dependency_cas_verified']);self::assertFalse($a['source_approval_cas_verified']);self::assertFalse($a['dispatch_permitted']);self::assertGreaterThan(0,$a['business_review_audit_id']);
  WP_Session_Tokens::get_instance($this->fixture->reviewer)->destroy_all();self::assertIsArray(Association::read($scope,1,$m,$s,$plan),'Historical reviewer logout alone does not revoke a durable approval.');
  $reviewer=get_userdata($this->fixture->reviewer);$reviewer->add_cap('manage_digiforge_products',false);try{self::assertWPError(Association::read($scope,1,$m,$s,$plan),'Revoked source-review module authority must invalidate the association.');}finally{$reviewer->add_cap('manage_digiforge_products',true);}
  PortalAccessFixture::login($this->fixture->grantor);$acl=new DigiForge\Security\ShopAccessRepository();$state=PrintifyApiApprovalFixture::checked($acl->read($scope->shopKey));$grantId=null;$grant=null;foreach($state['grants']as $id=>$candidate)if($candidate['actor_id']===$this->fixture->reviewer&&!$candidate['revoked']){$grantId=$id;$grant=$candidate;break;}self::assertIsString($grantId);PrintifyApiApprovalFixture::checked($acl->revoke($scope->shopKey,$grantId,wp_generate_uuid4(),$state['revision']));$this->fixture->owner();self::assertWPError(Association::read($scope,1,$m,$s,$plan));
  PortalAccessFixture::login($this->fixture->grantor);$state=PrintifyApiApprovalFixture::checked($acl->read($scope->shopKey));PrintifyApiApprovalFixture::checked($acl->grant($this->fixture->reviewer,$scope->shopKey,$grant['role'],$grant['caps'],time()+1800,wp_generate_uuid4(),$state['revision']));$this->fixture->owner();self::assertWPError(Association::read($scope,1,$m,$s,$plan),'A newly granted assignment cannot revive an approval bound to the old assignment revision.');
  $third=PrintifyApiApprovalFixture::checked(Association::propose($scope,1,$m,$s,$plan,$source['source_hash'],4,time(),time()+1200,wp_generate_uuid4()));PortalAccessFixture::login($this->fixture->reviewer);PrintifyApiApprovalFixture::checked(Association::decide($scope,$this->fixture->reviewer,$m,$s,$plan,5,$third['proposal_hash'],'APPROVED',wp_generate_uuid4()));$this->fixture->owner();$a=PrintifyApiApprovalFixture::checked(Association::read($scope,1,$m,$s,$plan));self::assertSame(3,$a['association_version']);
  global $wpdb;self::assertSame(1,$wpdb->update(Tables::audit_log(),['actor_id'=>1],['id'=>$a['business_review_audit_id']],['%d'],['%d']));self::assertWPError(Association::read($scope,1,$m,$s,$plan));
 }
}
